:host {
				display: block;
				min-width: 0;
			}
			h5 {
				margin: 0 0 10px;
				font-size: 13px;
				font-weight: 600;
				color: var(--nuxeo-text-default);
			}
			.tags {
				display: flex;
				flex-wrap: wrap;
				gap: 6px;
			}
			.tags:not(:empty) {
				margin-bottom: 10px;
			}
			.tag-chip {
				display: inline-flex;
				align-items: center;
				gap: 5px;
				max-width: 100%;
				min-height: 26px;
				padding: 2px 6px 2px 10px;
				border-radius: 4px;
				background: var(--nuxeo-hover-background, #f1f3f5);
				color: var(--nuxeo-text-default);
				font-size: 12px;
				font-weight: 400;
			}
			.tag-label {
				overflow-wrap: anywhere;
			}
			.tag-chip button {
				flex: 0 0 22px;
				width: 22px;
				height: 22px;
				padding: 0;
				border: 0;
				border-radius: 3px;
				background: transparent;
				color: var(--bs-secondary-color);
				font-size: 18px;
				line-height: 1;
			}
			.tag-chip button:hover {
				background: #0000000a;
				color: var(--nuxeo-text-default);
			}
			.tag-chip button:focus-visible {
				outline: 2px solid var(--nuxeo-primary-color, #06f);
				outline-offset: 1px;
			}
			.tag-status {
				font-size: 12px;
				color: var(--bs-secondary-color);
				margin: 6px 0 0;
			}
			.tag-option-label {
				overflow-wrap: anywhere;
			}
			small {
				color: var(--bs-secondary-color);
				font-size: 11px;
				margin-inline-start: auto;
				white-space: nowrap;
			}
			.create-tag {
				display: flex;
				align-items: baseline;
				gap: 6px;
				white-space: normal;
				overflow-wrap: anywhere;
			}
			.create-tag strong {
				font-weight: 500;
			}
			:host ::ng-deep .tag-picker.ng-select .ng-select-container {
				min-height: 36px;
				height: 36px;
				background: var(--nuxeo-box, #fff);
				border: 1px solid var(--nuxeo-border, #dce0e5);
				border-radius: 4px;
				font-size: 13px;
				box-shadow: none;
			}
			:host ::ng-deep .tag-picker.ng-select.ng-select-focused .ng-select-container {
				border-color: var(--nuxeo-primary-color, #06f);
				box-shadow: 0 0 0 2px #0066ff12;
			}
			:host ::ng-deep .tag-picker .ng-placeholder {
				color: var(--bs-secondary-color);
			}
			:host ::ng-deep .tag-picker .ng-input > input {
				font-size: 13px;
				border: 0;
				outline: none;
				padding: 0;
				color: var(--nuxeo-text-default);
				box-shadow: none;
			}
			:host ::ng-deep .tag-picker .ng-dropdown-panel {
				margin-top: 4px;
				border: 1px solid var(--nuxeo-border, #dce0e5);
				border-radius: 5px;
				box-shadow: 0 6px 18px #00000014;
				overflow: hidden;
				background: var(--nuxeo-box, #fff);
			}
			:host ::ng-deep .tag-picker .ng-dropdown-panel .ng-option {
				display: flex;
				align-items: center;
				gap: 12px;
				padding: 10px 12px;
				font-size: 13px;
				color: var(--nuxeo-text-default);
				background: var(--nuxeo-box, #fff);
				white-space: normal;
			}
			:host ::ng-deep .tag-picker .ng-dropdown-panel .ng-option-marked {
				background: var(--nuxeo-hover-background, #f3f6fa);
			}
			:host ::ng-deep .tag-picker .ng-option.ng-tag {
				border-top: 1px solid var(--nuxeo-border, #e8ebee);
			}

:host(.scoped-content),
			:host(.scoped-content) .folderish-layout {
				display: flex;
				flex: 1;
				flex-direction: column;
				min-height: 0;
				min-width: 0;
			}
			.folderish-layout {
				min-width: 0;
			}

:host {
				display: block;
				min-width: 0;
				margin: 16px 16px 16px;
			}
			.folderish-details {
				background: var(--nuxeo-box, #fff);
				color: var(--nuxeo-text-default, #334);
				padding: 16px 16px 1px;
				box-shadow: 0 3px 5px rgb(0 0 0 / 4%);
			}
			summary {
				cursor: pointer;
				font-weight: 700;
				font-size: 14px;
				line-height: 20px;
				margin-bottom: 14px;
				list-style: none;
				width: fit-content;
			}
			summary::-webkit-details-marker {
				display: none;
			}
			summary::after {
				content: '⌄';
				display: inline-block;
				margin-inline-start: 0.4rem;
			}
			details[open] > summary::after {
				transform: rotate(180deg);
			}
			summary:focus-visible {
				outline: 2px solid var(--nuxeo-primary-color, #3458db);
				outline-offset: 4px;
			}
			.sections {
				display: flex;
				flex-wrap: wrap;
				justify-content: space-between;
				gap: 2rem;
				padding: 2rem 1rem 1rem;
			}
			.sections > section {
				flex: 1 1 230px;
				min-width: 0;
				max-width: 320px;
				overflow-wrap: anywhere;
			}
			h3 {
				font-size: 14px;
				font-weight: 600;
				margin: 0 0 1.5rem;
			}
			dl {
				display: grid;
				grid-template-columns: max-content minmax(0, 1fr);
				gap: 0.7rem 0.8rem;
				margin: 0;
				font-size: 12px;
			}
			dt {
				font-weight: 400;
			}
			dd {
				margin: 0;
			}
			.person,
			.state {
				display: inline-block;
				border-radius: 1rem;
				padding: 0.1rem 0.5rem;
				background: var(--nuxeo-background, #f4f4f6);
				color: inherit;
				text-decoration: none;
			}
			.person:hover {
				text-decoration: underline;
			}
			.people {
				display: flex;
				flex-wrap: wrap;
				gap: 0.3rem;
			}
			.property {
				margin-bottom: 1rem;
				font-size: 13px;
			}
			.property-label {
				display: block;
				margin-bottom: 0.25rem;
			}
			.value {
				white-space: pre-wrap;
			}
			.event {
				font-size: 12px;
			}
			time {
				opacity: 0.7;
			}
			@media (max-width: 600px) {
				.sections {
					padding: 1.5rem 0 0.5rem;
					gap: 1.5rem;
				}
				.sections > section {
					max-width: none;
					flex-basis: 100%;
				}
			}

