:host {
				display: block;
				min-width: 0;
			}
			.metadata-content {
				padding-block: 16px;
			}
			.document-status {
				padding: 16px 0 24px;
			}
			.state-pill {
				background: var(--nuxeo-background, #f4f4f6);
				border-radius: 12px;
				padding: 3px 9px;
				text-transform: capitalize;
				font-size: 11px;
			}
			.person-pill {
				display: inline-flex;
				align-items: center;
				gap: 5px;
				padding-inline-end: 8px;
				border-radius: 12px;
				background: var(--nuxeo-background, #f4f4f6);
				font-size: 11px;
			}
			.person-avatar {
				display: inline-flex;
				align-items: center;
				justify-content: center;
				border-radius: 50%;
				width: 20px;
				height: 20px;
				background: #9254a3;
				color: white;
				font-size: 9px;
			}
			.people {
				display: flex;
				flex-wrap: wrap;
				gap: 4px;
			}
			.asset-tags {
				margin-block: 24px 32px;
			}
			.asset-tags ::ng-deep h5 {
				font-size: 13px;
				font-weight: 600;
			}

			.activity {
				border: 0;
			}
			.activity ::ng-deep nx-comments > h5,
			.activity ::ng-deep nx-comments > small {
				display: none;
			}
			.activity ::ng-deep textarea {
				border: 0;
				border-bottom: 1px solid var(--nuxeo-border);
				border-radius: 0;
				min-height: 40px;
				font-size: 12px;
			}
			.activity .nav-link {
				border: 0;
				color: var(--bs-secondary-color);
				border-radius: 0;
			}
			.activity .nav-link.active {
				color: var(--nuxeo-primary-color);
				border-bottom: 2px solid var(--nuxeo-primary-color);
				background: transparent;
			}
			.details-panel {
				overflow: auto;
				padding: 0.75rem 1rem 1rem;
			}
			.details-section {
				margin-bottom: 0.75rem;
				border-block-end: 1px solid var(--bs-border-color);
				padding-block-end: 0.75rem;
			}
			.details-section:last-child {
				margin-bottom: 0;
			}
			summary {
				cursor: pointer;
				font-size: 0.875rem;
				font-weight: 600;
				margin-bottom: 0.75rem;
			}
			.details-body {
				padding-top: 0.75rem;
			}
			dl {
				display: grid;
				grid-template-columns: max-content minmax(0, 1fr);
				gap: 0.5rem 0.75rem;
				margin: 0;
				font-size: 12px;
			}
			dt {
				color: var(--bs-secondary-color);
				font-weight: 500;
			}
			dd {
				margin: 0;
				overflow-wrap: anywhere;
			}
			.version-selector summary {
				font-weight: 400;
				margin: 0;
			}
			.version-selector[open] {
				grid-column: 1 / -1;
			}
			.technical-list {
				font-size: 0.8125rem;
			}
			.tags {
				display: flex;
				flex-wrap: wrap;
				gap: 0.35rem;
			}
			.activity .nav {
				margin-bottom: 0.75rem;
			}
			.nav-link {
				font-size: 0.875rem;
				padding: 0.35rem 0.6rem;
			}

:host {
				display: block;
				font-size: 12px;
			}
			header,
			.actions,
			.attachment {
				display: flex;
				align-items: center;
				gap: 8px;
			}
			header {
				justify-content: space-between;
				margin-bottom: 16px;
			}
			h3 {
				font-size: 13px;
				font-weight: 600;
				margin: 0;
			}
			button {
				border: 0;
				background: transparent;
				color: var(--nuxeo-primary-color);
				padding: 4px;
			}
			nx-webui-icon {
				width: 18px;
				height: 18px;
			}
			.field {
				margin-bottom: 16px;
			}
			.field-label {
				font-weight: 400;
				margin-bottom: 4px;
			}
			.value {
				white-space: pre-wrap;
				overflow-wrap: anywhere;
			}
			.attachments {
				margin-top: 24px;
			}
			.attachments h3 {
				margin-bottom: 12px;
			}
			.download {
				overflow-wrap: anywhere;
				text-align: start;
				flex: 1;
			}
			.upload {
				display: block;
				text-align: center;
				padding: 16px;
				border: 2px dashed var(--nuxeo-border, #ddd);
				margin-top: 12px;
				cursor: pointer;
			}
			.upload {
				position: relative;
			}
			.upload input {
				position: absolute;
				inset: 0;
				width: 100%;
				opacity: 0;
				cursor: pointer;
			}
			.upload:focus-within {
				outline: 2px solid var(--nuxeo-primary-color);
			}
			[role='alert'] {
				color: var(--bs-danger);
			}
